/usr/bin/zsh -lc "node --check app.js && node --input-type=module <<'NODE'
import puppeteer from '/tmp/qs-hf-probe/node_modules/puppeteer-core/lib/puppeteer/puppeteer-core.js';
import assert from 'node:assert/strict';
import {mkdir} from 'node:fs/promises';
const root='/tmp/qs-frontend-trial-7JuiYG';
await mkdir(root+'/evidence',{recursive:true});
const browser=await puppeteer.launch({executablePath:'/home/djn12313/.cache/ms-playwright/chromium_headless_shell-1234/chrome-headless-shell-linux64/chrome-headless-shell',headless:true,args:['--no-sandbox','--disable-dev-shm-usage','--disable-background-networking']});
try {
 const page=await browser.newPage();
 const errors=[]; const blocked=[];
 page.on('pageerror',e=>errors.push(e.message));
 await page.setRequestInterception(true);
 page.on('request',r=>{if(r.url().startsWith('file:'))r.continue();else{blocked.push(r.url());r.abort();}});
 const results=[];
 for(const viewport of [{width:1280,height:900},{width:390,height:844}]){
  await page.setViewport(viewport);
  await page.goto('file://'+root+'/index.html');
  assert.equal(await page.title(),'Membership — Northstar Museum');
  assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),'No horizontal overflow');
  for(const id of ['site-header','site-footer','membership-panel','membership-title','price','member-count','annual-visits','founded','join-form','member-email','join-button','form-message','details-link']) assert.equal(await page."'$$eval('"'#'+id,els=>els.length),1,id);
  assert.equal(await page."'$eval('"'#details-link',el=>el.getAttribute('href')),'/membership/family');
  assert.equal(await page."'$eval('"'#join-form',el=>el.getAttribute('action')),'/join/checkout?plan=family');
  assert.equal(await page."'$eval('"'body',el=>getComputedStyle(el).fontFamily), 'Georgia, \"Times New Roman\", serif');
  await page.screenshot({path:root+'/evidence/'+(viewport.width===1280?'wide':'narrow')+'.png',fullPage:true});
  await page.keyboard.press('Tab');
  assert.equal(await page.evaluate(()=>document.activeElement.textContent),'Skip to content');
  await page.keyboard.press('Enter');
  await page.focus('#member-email');
  await page.keyboard.press('Tab');
  assert.equal(await page.evaluate(()=>document.activeElement.id),'join-button');
  const focus=await page."'$eval('"'#join-button',el=>getComputedStyle(el).outlineStyle);
  assert.equal(focus,'solid');
  await page.keyboard.press('Enter');
  assert.equal(await page.evaluate(()=>window.__events?.length||0),0);
  await page.type('#member-email','invalid');
  await page.click('#join-button');
  assert.equal(await page.evaluate(()=>window.__events?.length||0),0);
  assert.equal(await page."'$eval('"'#member-email',el=>el.validity.typeMismatch),true);
  await page."'$eval('"'#member-email',el=>{el.value='';});
  await page.type('#member-email','family@example.com');
  await page.keyboard.press('Enter');
  assert.deepEqual(await page.evaluate(()=>window.__events),[{name:'join_started',plan:'family'}]);
  assert.equal(await page."'$eval('"'#form-message',el=>el.textContent),'Ready to continue with Family membership.');
  assert.ok(page.url().startsWith('file://'+root+'/index.html'));
  assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));
  await page.emulateMediaFeatures([{name:'prefers-reduced-motion',value:'reduce'}]);
  assert.equal(await page.evaluate(()=>matchMedia('(prefers-reduced-motion: reduce)').matches),true);
  assert.equal(await page."'$eval('"'#join-button',el=>getComputedStyle(el).animationName),'none');
  results.push({viewport,overflow:false,requiredIds:true,keyboard:true,invalidBlocked:true,validConfirmation:true,event:true,reducedMotion:true});
 }
 assert.deepEqual(errors,[]);assert.deepEqual(blocked,[]);
 console.log(JSON.stringify({checks:'passed',results,browserErrors:errors,externalRequests:blocked,screenshots:['evidence/wide.png','evidence/narrow.png']},null,2));
} finally {await browser.close();}
NODE"

